        let (rvpb, rvb, rvs) = find_rowreg_blocks(&func).expect("row-register blocks present");
        assert_eq!(rowreg_count_in(&func, rvpb, X86Opcode::MovdquRM), 4);
        assert_eq!(rowreg_count_in(&func, rvs, X86Opcode::MovdquMR), 4);
